void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = pow(texture(iChannel3,uv).xyz,vec3(1.0/2.2));

    // Output to screen
    fragColor = vec4(col,1.0);
}

#define T(U) texelFetch( iChannel3, ivec2(U), 0 )

float colorDistance(in vec3 c1, in vec3 c2) {
    c1 = c1 * (2., 4., 3.);
    c2 = c2 * (2., 4., 3.);
    return dot(c1-c2,c1-c2);
}

#define N 10

//Current Processing Buffer.
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 ij = ivec2(fragCoord);
    vec4 V = T(vec2(1,0));
    if ( V.x == 0. && iChannelResolution[0].x > 0. )  { 
        if ((ij.x == 1) && (ij.y == 1)) {
            fragColor = vec4(1.);
        } else {
            fragColor = vec4(vec3(0.),1.);
        }
    } else {
        vec4 w_col = texelFetch(iChannel2, ij + ivec2(-1,0), 0);
        vec4 sww_col = texelFetch(iChannel2, ij + ivec2(2,-1), 0);
        fragColor = max(w_col, sww_col);
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 palette[N];
    palette[0] = vec3(0.1,0.5,0.1);
    palette[1] = vec3(0.5,0.1,0.1);
    palette[2] = vec3(0.1,0.1,0.5);
    palette[3] = vec3(0.9,0.5,0.9);
    palette[4] = vec3(0.9,0.9,0.5);
    palette[5] = vec3(0.5,0.9,0.9);
    palette[6] = vec3(1.0,1.0,1.0);
    palette[7] = vec3(0.67,0.67,0.67);
    palette[8] = vec3(0.33,0.33,0.33);
    palette[9] = vec3(0.0,0.0,0.0);

    vec4 V = T(vec2(1,0));
    if ( V.x == 0. && iChannelResolution[0].x > 0. )  { 
        fragColor = vec4(vec3(0.5), 1.);
    } else {

    ivec2 ij = ivec2(fragCoord);
    vec3 cur_err = texelFetch(iChannel2, ij, 0).xyz * 2. - 1.;
    ivec2 w_ij = ij + ivec2(-1,0);
    ivec2 s_ij = ij + ivec2(0,-1);
    ivec2 sw_ij = ij + ivec2(-1,-1);
    ivec2 se_ij = ij + ivec2(1,-1);

    float proc_w = texelFetch(iChannel1, w_ij, 0).x;
    float proc_s = texelFetch(iChannel1, s_ij, 0).x;
    float proc_sw = texelFetch(iChannel1, sw_ij, 0).x;
    float proc_se = texelFetch(iChannel1, se_ij, 0).x;

    if (proc_w > 0.5) {
        vec3 col = texelFetch(iChannel3, w_ij, 0).xyz;
        vec3 err = texelFetch(iChannel2, w_ij, 0).xyz * 2. - 1.;
        float mindist = 100.;
        vec3 bin;
        for(int i=0; i<N; i++) {
            float dist = colorDistance(col+err,palette[i]);
            if (dist < mindist) {
                mindist = dist;
                bin = palette[i];
            }
        }
        cur_err += 7.*(col+err-bin)/16.;
    }
    if (proc_s > 0.5) {
        vec3 col = texelFetch(iChannel3, s_ij, 0).xyz;
        vec3 err = texelFetch(iChannel2, s_ij, 0).xyz * 2. - 1.;
        float mindist = 100.;
        vec3 bin;
        for(int i=0; i<N; i++) {
            float dist = colorDistance(col+err,palette[i]);
            if (dist < mindist) {
                mindist = dist;
                bin = palette[i];
            }
        }
        cur_err += 5.*(col+err-bin)/16.;
    }
    if (proc_sw > 0.5) {
        vec3 col = texelFetch(iChannel3, sw_ij, 0).xyz;
        vec3 err = texelFetch(iChannel2, sw_ij, 0).xyz * 2. - 1.;
        float mindist = 100.;
        vec3 bin;
        for(int i=0; i<N; i++) {
            float dist = colorDistance(col+err,palette[i]);
            if (dist < mindist) {
                mindist = dist;
                bin = palette[i];
            }
        }
        cur_err += 1.*(col+err-bin)/16.;
    }
    if (proc_se > 0.5) {
        vec3 col = texelFetch(iChannel3, s_ij, 0).xyz;
        vec3 err = texelFetch(iChannel2, s_ij, 0).xyz * 2. - 1.;
        float mindist = 100.;
        vec3 bin;
        for(int i=0; i<N; i++) {
            float dist = colorDistance(col+err,palette[i]);
            if (dist < mindist) {
                mindist = dist;
                bin = palette[i];
            }
        }
        cur_err += 3.*(col+err-bin)/16.;
    }
    fragColor = vec4((cur_err+1.)/2., 1.);

    }
}

void mainImage( out vec4 O, in vec2 U )
{
    vec3 palette[N];
    palette[0] = vec3(0.1,0.5,0.1);
    palette[1] = vec3(0.5,0.1,0.1);
    palette[2] = vec3(0.1,0.1,0.5);
    palette[3] = vec3(0.9,0.5,0.9);
    palette[4] = vec3(0.9,0.9,0.5);
    palette[5] = vec3(0.5,0.9,0.9);
    palette[6] = vec3(1.0,1.0,1.0);
    palette[7] = vec3(0.67,0.67,0.67);
    palette[8] = vec3(0.33,0.33,0.33);
    palette[9] = vec3(0.0,0.0,0.0);

    ivec2 ij = ivec2(U);
    vec2 uv = U/iResolution.xy;

    // initialization from https://www.shadertoy.com/view/tsjGRm
    vec2 R = iResolution.xy;
    U -= .5;
    if ( U == vec2(0,0) ) { O = vec4(R, O.xy); return; }
    // TODO : use this to reload on screen size update
    vec4 V = T(vec2(0,0));
    if ( R != V.xy) {
        vec3 col = pow(texture(iChannel0, uv).xyz,vec3(2.2));
        O = vec4(col, 1.);
    };
    if ( U == vec2(1,0) ) { O = vec4( iChannelResolution[0].xy, O.xy ); return; }
    V = T(vec2(1,0));
    if ( V.x == 0. && iChannelResolution[0].x > 0. )  { 
        vec3 col = pow(texture(iChannel0, uv).xyz,vec3(2.2));
        O = vec4(col, 1.); 
    } else {
        vec3 col = texelFetch(iChannel3, ij, 0).xyz;

        float proc_curr = texelFetch(iChannel1, ij, 0).x;
        if (proc_curr > 0.5) {
            vec3 err = texelFetch(iChannel2, ij, 0).xyz * 2. - 1.;
            float mindist = 100.;
            vec3 bin;
            for(int i=0; i<N; i++) {
                float dist = colorDistance(col+err,palette[i]);
                if (dist < mindist) {
                    mindist = dist;
                    bin = palette[i];
                }
            }
            O = vec4(bin,1.);
        } else {
            O = vec4(col,1.);
        }

    }
}
